def share(self, with_user, roles=None, table=None):
        """
        Give cube access rights to another user

        Not, this method is NOT supported by SQLite3!
        """
        if self.db.driver == 'sqlite3':
            raise NotImplementedError('SQLite3 does not support sharing cubes.')

        if roles is None:
            roles = []

        if isinstance(roles, str):
            roles = [roles]

        if isinstance(with_user, str):
            with_user = self.db.get_user(with_user)

        if isinstance(with_user, list):
            for user in with_user:
                self.share(user, roles, table)
            return

        if with_user.id not in self.share_with:
            self.share_with.append(with_user.id)

        if table is None:
            table = self.table

        if table not in self.share_with_table:
            self.share_with_table[table] = []

        if with_user.id not in self.share_with_table[table]:
            self.share_with_table[table].append(with_user.id)

        if table not in self.share_with_roles:
            self.share_with_roles[table] = {}

        if with_user.id not in self.share_with_roles[table]:
            self.share_with_roles[table][with_user.id] = []

        for role in roles:
            if role not in self.share_with_roles[table][with_user.id]:
                self.share_with_roles[table][with_user.id].append(role)

        self.save()

